    imageHint: "serra do geres mountain landscape",
    descriptionAdvanced: {
      de: "Die Serra do Gerês ist ein Gebirgszug im Nordwesten Portugals und Teil des Nationalparks Peneda-Gerês. Sie erreicht Höhen bis zu 1.546 Metern am Pico da Nevosa. Das Relief ist geprägt von Granitfelsen, tiefen Tälern und Wasserfällen. Es gibt zahlreiche Wanderwege, darunter die PR7. Die Serra ist bekannt für ihre wilde Schönheit und Biodiversität. Die Flora umfasst Stechpalmen und Kiefern. Die Fauna umfasst den Iberischen Wolf und Steinadler. Das Klima ist atlantisch mit hohen Niederschlägen. Im Winter liegt oft Schnee. Die Serra ist ein wichtiges Wassereinzugsgebiet. Es gibt mehrere Stauseen wie den Caniçada-See. Die traditionelle Landwirtschaft umfasst Viehzucht. Die Dörfer sind abgelegen. Die Serra do Gerês ist ein beliebtes Ziel für Naturliebhaber. Die höchsten Gipfel bieten weite Ausblicke. Das Gebiet ist seit 1971 Nationalpark.",
      hu: "A Serra do Gerês egy hegyvidék Északnyugat-Portugáliában, a Peneda-Gerês Nemzeti Park része. Magassága eléri az 1546 métert a Pico da Nevosa csúcsán. A reliefet gránitsziklák, mély völgyek és vízesések jellemzik. Számos túraútvonal található, köztük a PR7. A Serra vad szépségéről és biodiverzitásáról ismert. A növényvilág magába foglalja a magyalt és a fenyőt. Az állatvilág az ibériai farkast és a szirti sast. Az éghajlat atlanti, magas csapadékkal. Télen gyakori a hó. A Serra fontos vízgyűjtő terület. Több víztározó is van, mint a Caniçada-tó. A hagyományos mezőgazdaság állattenyésztést foglal magában. A falvak elszigeteltek. A Serra do Gerês népszerű a természetkedvelők körében. A legmagasabb csúcsok széles kilátást nyújtanak. A terület 1971 óta nemzeti park.",
      ro: "Serra do Gerês este un lanț muntos în nord-vestul Portugaliei, parte a Parcului Național Peneda-Gerês. Atinge înălțimi de până la 1.546 de metri la Pico da Nevosa. Relieful este caracterizat de stânci de granit, văi adânci și cascade. Există numeroase trasee de drumeție, inclusiv PR7. Serra este cunoscută pentru frumusețea sălbatică și biodiversitate. Flora include ilice și pini. Fauna include lupul iberic și acvila de munte. Clima este atlantică, cu precipitații mari. Iarna, zăpada este frecventă. Serra este un important bazin hidrografic. Există mai multe lacuri de acumulare, precum Caniçada. Agricultura tradițională include creșterea animalelor. Satele sunt izolate. Serra do Gerês este o destinație populară pentru iubitorii de natură. Cele mai înalte vârfuri oferă vederi panoramice. Zona este parc național din 1971.",
      en: "The Serra do Gerês is a mountain range in northwestern Portugal, part of the Peneda-Gerês National Park. It reaches heights up to 1,546 meters at Pico da Nevosa. The relief is characterized by granite outcrops, deep valleys, and waterfalls. There are many hiking trails, including PR7. The Serra is known for its wild beauty and biodiversity. Flora includes holly and pines. Fauna includes the Iberian wolf and golden eagle. The climate is Atlantic with high rainfall. Snow is common in winter. The Serra is an important watershed. There are several reservoirs like Lake Caniçada. Traditional agriculture includes livestock. Villages are remote. Serra do Gerês is a popular destination for nature lovers. The highest peaks offer panoramic views. The area has been a national park since 1971.",
      es: "La Serra do Gerês es una cadena montañosa en el noroeste de Portugal y forma parte del Parque Nacional de Peneda-Gerês. Alcanza alturas de hasta 1.546 metros en el Pico da Nevosa. El relieve está marcado por rocas de granito, valles profundos y cascadas. Existen numerosos senderos, como el PR7. La sierra es conocida por su belleza salvaje y biodiversidad. La flora incluye acebos y pinos. La fauna cuenta con el lobo ibérico y el águila real. El clima es atlántico con altas precipitaciones. En invierno suele nevar. La sierra es una importante cuenca hidrográfica. Existen varios embalses como el lago Caniçada. La agricultura tradicional incluye la ganadería. Los pueblos son remotos. La Serra do Gerês es un destino popular para los amantes de la naturaleza. Las cumbres más altas ofrecen amplias vistas. El área es Parque Nacional desde 1971.",
      pt: "A Serra do Gerês é uma cordilheira no noroeste de Portugal e faz parte do Parque Nacional da Peneda-Gerês. Atinge altitudes de até 1.546 metros no Pico da Nevosa. O relevo é marcado por rochas de granito, vales profundos e cascatas. Existem inúmeros trilhos pedestres, incluindo o PR7. A serra é conhecida pela sua beleza selvagem e biodiversidade. A flora inclui azevinhos e pinheiros. A fauna abrange o lobo-ibérico e a águia-real. O clima é atlântico com elevadas precipitações. No inverno neva frequentemente. A serra é uma importante bacia hidrográfica. Existem várias albufeiras, como a da Caniçada. A agricultura tradicional inclui a pecuária. As aldeias são isoladas. A Serra do Gerês é um destino popular para os amantes da natureza. Os cumes mais altos oferecem vistas vastas. A área é Parque Nacional desde 1971.",
      fr: "La Serra do Gerês est une chaîne de montagnes du nord-ouest du Portugal, intégrée au parc national de Peneda-Gerês. Elle culmine à 1 546 mètres au Pico da Nevosa. Le relief est marqué par des rochers de granit, des vallées profondes et des cascades. De nombreux sentiers de randonnée, dont le PR7, la parcourent. La Serra est réputée pour sa beauté sauvage et sa biodiversité. La flore comprend des houx et des pins. La faune inclut le loup ibérique et l'aigle royal. Le climat est atlantique avec de fortes précipitations. La neige est fréquente en hiver. La Serra est un bassin versant important. On y trouve plusieurs réservoirs comme le lac de Caniçada. L'agriculture traditionnelle comprend l'élevage. Les villages sont isolés. La Serra do Gerês est une destination prisée des amoureux de la nature. Les plus hauts sommets offrent des panoramas étendus. La zone est classée parc national depuis 1971.",
    },
