    imageHint: "serra da arada mountains",
    descriptionAdvanced: {
      de: "Die Serra da Arada ist ein Gebirgsmassiv im Norden Portugals, das sich über die Distrikte Aveiro und Viseu erstreckt. Der höchste Punkt ist der Caramulo mit 1.075 Metern. Die Landschaft ist geprägt von Granitfelsen und urzeitlichen Wäldern, darunter Eichen und Kiefern. In der Region gibt es mehrere Thermalquellen, die bereits von den Römern genutzt wurden. Die Serra da Arada ist Teil des Natura 2000-Netzwerks und beherbergt seltene Vogelarten wie den Steinadler. Wirtschaftlich spielen Forstwirtschaft und Tourismus eine Rolle. Die Dörfer in der Umgebung, wie Arouca und São Pedro do Sul, sind für ihre traditionelle Architektur bekannt. Das Klima ist feucht und mild mit jährlichen Niederschlägen um 1.500 mm. Geologisch dominieren Granite aus dem Karbon. Der Name 'Arada' leitet sich wahrscheinlich von 'Arade' ab, einem lokalen Begriff für felsiges Gelände.",
      hu: "A Serra da Arada egy hegyvonulat Észak-Portugáliában, amely az Aveiro és Viseu kerületek határán fekszik. Legmagasabb csúcsa a Caramulo, 1075 méterrel. A tájat gránitsziklák és ősi erdők jellemzik, ahol a kocsánytalan tölgy és a fenyő a domináns. A hegység híres forró vizű forrásairól, amelyeket már a rómaiak is használtak. A terület a Natura 2000 hálózat része, és számos madárfaj, köztük a szirti sas is előfordul. A gazdaságot az erdőgazdálkodás és a turizmus határozza meg. A környező falvak, mint Arouca és São Pedro do Sul, hagyományos kőépületeikről ismertek. Az éghajlat nedves és mérsékelt, évi 1500 mm csapadékkal. Geológiailag a karbon időszaki gránitok jellemzőek. Nevét a 'Arade' szóból eredeztetik, ami sziklás terepet jelent.",
      ro: "Serra da Arada este un masiv muntos din nordul Portugaliei, situat la granița dintre districtele Aveiro și Viseu. Altitudinea maximă este de 1.075 m, în vârful Caramulo. Peisajul este dominat de stânci de granit și păduri seculare de stejar și pin. Zona este cunoscută pentru izvoarele termale, utilizate încă din epoca romană. Face parte din rețeaua Natura 2000, găzduind specii rare de păsări, cum ar fi acvila de munte. Economia locală se bazează pe silvicultură și turism. Satele din apropiere, precum Arouca și São Pedro do Sul, păstrează arhitectura tradițională din piatră. Clima este umedă și blândă, cu precipitații anuale de aproximativ 1.500 mm. Geologia este dominată de granituri carbonifere. Numele 'Arada' provine probabil din cuvântul 'Arade', care înseamnă teren stâncos.",
      en: "Serra da Arada is a mountain massif in northern Portugal, straddling the districts of Aveiro and Viseu. Its highest peak is Caramulo at 1,075 meters. The landscape features rugged granite outcrops and ancient forests of oak and pine. The region is renowned for its thermal springs, exploited since Roman times. It is part of the Natura 2000 network, hosting rare bird species such as the golden eagle. Forestry and tourism are key economic activities. Nearby villages like Arouca and São Pedro do Sul showcase traditional granite architecture. The climate is Atlantic, with mild temperatures and annual rainfall around 1,500 mm. Geologically, the massif is composed of Carboniferous granites. The name 'Arada' is thought to derive from 'Arade,' a local term for rocky terrain. The area offers hiking trails and scenic viewpoints.",
      es: "La Serra da Arada es un macizo montañoso en el norte de Portugal que se extiende por los distritos de Aveiro y Viseu. El punto más alto es el Caramulo con 1.075 metros. El paisaje se caracteriza por rocas de granito y bosques milenarios, incluidos robles y pinos. En la región hay varias fuentes termales que ya eran utilizadas por los romanos. La Serra da Arada forma parte de la red Natura 2000 y alberga aves poco comunes como el águila real. Económicamente, la silvicultura y el turismo desempeñan un papel importante. Los pueblos de los alrededores, como Arouca y São Pedro do Sul, son conocidos por su arquitectura tradicional. El clima es húmedo y suave, con precipitaciones anuales de unos 1.500 mm. Geológicamente dominan los granitos del Carbonífero. El nombre 'Arada' probablemente deriva de 'Arade', un término local para terrenos rocosos.",
      pt: "A Serra da Arada é um maciço montanhoso no norte de Portugal, que se estende pelos distritos de Aveiro e Viseu. O ponto mais alto é o Caramulo com 1.075 metros. A paisagem é caracterizada por penedos de granito e florestas ancestrais, incluindo carvalhos e pinheiros. Na região existem várias fontes termais, que já eram utilizadas pelos romanos. A Serra da Arada faz parte da rede Natura 2000 e alberga espécies de aves raras como a águia-real. Economicamente, a silvicultura e o turismo desempenham um papel relevante. As aldeias vizinhas, como Arouca e São Pedro do Sul, são conhecidas pela sua arquitetura tradicional. O clima é húmido e ameno com precipitação anual em torno de 1.500 mm. Geologicamente dominam os granitos do Carbónico. O nome 'Arada' deriva provavelmente de 'Arade', um termo local para terreno rochoso.",
      fr: "La Serra da Arada est un massif montagneux du nord du Portugal, s'étendant sur les districts d'Aveiro et de Viseu. Le point culminant est le Caramulo à 1 075 mètres. Le paysage est marqué par des rochers de granit et des forêts primaires, notamment de chênes et de pins. La région compte plusieurs sources thermales déjà utilisées par les Romains. La Serra da Arada fait partie du réseau Natura 2000 et abrite des espèces d'oiseaux rares comme l'aigle royal. Sur le plan économique, la sylviculture et le tourisme jouent un rôle important. Les villages environnants, tels qu'Arouca et São Pedro do Sul, sont réputés pour leur architecture traditionnelle. Le climat est humide et doux, avec des précipitations annuelles d'environ 1 500 mm. Géologiquement, les granites du Carbonifère dominent. Le nom 'Arada' dérive probablement d'Arade, un terme local désignant un terrain rocheux.",
    },
