      pt: ["Região fronteiriça do Douro.", "Clima seco.", "Pouca infraestrutura.", "Maciço granítico."],
      fr: ["Région frontalière du Douro.", "Climat sec.", "Peu d'infrastructures.", "Massif granitique."],
