      es: ["Cima más alta: Trevim, 1.204 m", "Distancia a Coímbra: unos 25 km", "Principales tipos de roca: cuarcita y pizarra", "Pueblos de pizarra más conocidos: Talasnal, Gondramaz", "Temperatura media en verano: 20°C", "El área forestal abarca unas 15.000 hectáreas"],
