      fr: ["Sommet le plus élevé : Trevim, 1 204 m", "Distance de Coimbra : environ 25 km", "Principales roches : quartzite et schiste", "Villages de schiste célèbres : Talasnal, Gondramaz", "Température moyenne en été : 20°C", "La zone forestière couvre environ 15 000 hectares"],
