    imageHint: "serra do montemuro south slope",
    descriptionAdvanced: {
      de: "Die Serra do Montemuro ist das achthöchste Gebirge des portugiesischen Festlandes und erreicht am Pico de São Cristóvão eine Höhe von 1.382 Metern. Dieses Granitmassiv liegt zwischen den Flüssen Douro und Vouga und bildet eine bedeutende natürliche Barriere im Norden des Landes. Das südliche Relief ist durch weite Plateaus und tiefe Täler geprägt, in denen trotz der harten Winterbedingungen noch traditionelle Weidewirtschaft betrieben wird. Die Region ist Teil des Natura-2000-Netzwerks, da sie wichtige Lebensräume für den Iberischen Wolf und verschiedene Greifvögel bietet. Historisch ist das Gebiet seit der Vorgeschichte besiedelt, was durch zahlreiche Megalithanlagen auf den Höhenzügen belegt wird. Heute spielt das Gebirge zudem eine wichtige Rolle bei der Erzeugung erneuerbarer Energien durch mehrere Windparks auf den Bergrücken.",
      hu: "A Serra do Montemuro Portugália szárazföldi részének nyolcadik legmagasabb hegysége, amelynek legmagasabb pontja, a Pico de São Cristóvão 1382 méterrel magasodik a tengerszint fölé. A Douro és a Vouga folyók között elhelyezkedő gránitmasszívum jelentős természetes választóvonalat képez az ország északi részén. A déli domborzatot kiterjedt fennsíkok és mély völgyek jellemzik, ahol a zord téli körülmények ellenére a mai napig fennmaradt a hagyományos pásztorkodás. A terület a Natura 2000 hálózat része, mivel kritikus élőhelyet biztosít az ibériai farkasnak és számos ragadozó madárnak. Történelmileg a régió már a történelem előtti idők óta lakott, amit a hegység gerincein található megalitikus emlékek is bizonyítanak. Napjainkban a hegység fontos szerepet tölt be a megújuló energia termelésében a gerinceken elhelyezett szélerőműparkok révén.",
      ro: "Serra do Montemuro este al optulea cel mai înalt lanț muntos din Portugalia continentală, atingând o altitudine de 1.382 de metri în vârful Pico de São Cristóvão. Situat între râurile Douro și Vouga, acest masiv granitic formează o barieră naturală semnificativă în nordul țării. Relieful sudic este caracterizat prin podișuri extinse și văi adânci, unde păstoritul tradițional rămâne o activitate economică vitală în ciuda condițiilor aspre de iarnă. Regiunea face parte din rețeaua Natura 2000, oferind habitate importante pentru lupul iberic și diverse păsări de pradă. Din punct de vedere istoric, zona a fost locuită încă din preistorie, fapt dovedit de numeroasele monumente megalitice dispersate pe culmi. În prezent, muntele joacă un rol crucial în producerea de energie regenerabilă prin numeroasele parcuri eoliene instalate de-a lungul crestelor sale.",
      en: "The Serra do Montemuro is the eighth highest mountain range in mainland Portugal, reaching an elevation of 1,382 meters at the Pico de São Cristóvão. Located between the Douro and Vouga rivers, this granitic massif forms a significant natural barrier and is part of the Natura 2000 network due to its high ecological value. The southern relief is characterized by extensive plateaus and deep valleys, where traditional pastoralism remains a vital economic activity despite the harsh winter conditions. Historically, the region has been inhabited since prehistoric times, evidenced by various megalithic monuments scattered across the heights. The landscape is a mosaic of scrubland, rocky outcrops, and small patches of indigenous oak forests, providing a habitat for the Iberian wolf and various birds of prey. In recent years, the mountain has become an important site for renewable energy, with several wind farms installed along its ridges.",
      es: "La Serra do Montemuro Sur es una cadena montañosa en el norte de Portugal, conocida por sus valles escarpados y rocas graníticas. Las alturas alcanzan los 1.300 metros. La región está poco poblada y marcada por la agricultura, especialmente el cultivo de patatas y la ganadería. Los bosques se componen de pinos y abedules. En las cotas más altas hay turberas y brezales.",
      pt: "A Serra do Montemuro Sul é uma cordilheira no norte de Portugal, conhecida pelos seus vales íngremes e rochas graníticas. As altitudes atingem os 1.300 metros. A região é escassamente povoada e marcada pela agricultura, especialmente o cultivo da batata e a pecuária. As florestas consistem em pinheiros e bétulas. Nas altitudes mais elevadas existem turfeiras e charnecas.",
      fr: "La Serra do Montemuro Sud est une chaîne de montagnes du nord du Portugal, connue pour ses vallées escarpées et ses rochers granitiques. Les altitudes atteignent 1 300 mètres. La région est peu peuplée et marquée par l'agriculture, notamment la culture de la pomme de terre et l'élevage. Les forêts sont composées de pins et de bouleaux. Dans les zones les plus élevées, on trouve des tourbières et des landes.",
    },
    factsAdvanced: {
      de: ["Höchster Punkt ist der Pico de São Cristóvão mit 1.382 Metern.", "Das Gebirge gehört zum europäischen Schutzgebietsnetz Natura 2000.", "Geologisch besteht das Massiv überwiegend aus variszischem Granit.", "Es bildet die Wasserscheide zwischen den Einzugsgebieten von Douro und Vouga.", "Die Durchschnittstemperaturen liegen im Winter oft unter dem Gefrierpunkt.", "Zahlreiche Windkraftanlagen nutzen die exponierten Höhenlagen zur Stromerzeugung."],
      hu: ["A legmagasabb pont a Pico de São Cristóvão, 1382 méteres magassággal.", "A hegység az európai Natura 2000 természetvédelmi hálózat tagja.", "Geológiailag a masszívum túlnyomórészt variszkuszi gránitból épül fel.", "Vízválasztót képez a Douro és a Vouga folyók vízgyűjtő területei között.", "A téli átlaghőmérséklet gyakran fagypont alatt marad a magaslatokon.", "Számos szélerőművet telepítettek a gerincekre a megújuló energia kiaknázására."],
      ro: ["Punctul culminant este Pico de São Cristóvão, la 1.382 de metri.", "Munții sunt incluși în rețeaua europeană de protecție Natura 2000.", "Din punct de vedere geologic, masivul este compus predominant din granit variat.", "Formează cumpăna apelor între bazinele hidrografice Douro și Vouga.", "Temperaturile medii de iarnă scad frecvent sub pragul de îngheț.", "Numeroase turbine eoliene sunt instalate pe creste pentru energie verde."],
      en: ["The highest point is Pico de São Cristóvão at 1,382 meters.", "The range is part of the European Natura 2000 ecological network.", "Geologically, the massif consists mainly of Variscan granite.", "It serves as a watershed between the Douro and Vouga river basins.", "Winter temperatures frequently drop below freezing at higher altitudes.", "Several wind farms are situated along the ridges for power generation."],
      es: ["Punto más alto: 1.305 m", "Superficie: 140 km²", "Área de cultivo de patata: 20 km²", "Temperatura media: 9°C", "Precipitaciones: 1.500 mm/año", "Altitud de las turberas: más de 1.000 m"],
      pt: ["Ponto mais alto: 1.305 m", "Área: 140 km²", "Área de cultivo de batata: 20 km²", "Temperatura média: 9°C", "Precipitação: 1.500 mm/ano", "Altitude das turfeiras: acima de 1.000 m"],
      fr: ["Point culminant : 1 305 m", "Superficie : 140 km²", "Surface de culture de pommes de terre : 20 km²", "Température moyenne : 9°C", "Précipitations : 1 500 mm/an", "Altitude des tourbières : plus de 1 000 m"],
    },
