      es: "El flanco norte de la Serra da Gardunha es más sombrío y ofrece una vegetación más densa.",
      pt: "A encosta norte da Serra da Gardunha é mais sombria e oferece uma vegetação mais densa.",
      fr: "Le flanc nord de la Serra da Gardunha est plus ombragé et présente une végétation plus dense.",
